using CondoManager.Domain;
namespace CondoManager.Application;
public record MeetingInput(int ExpectedVersion,string Title,MeetingType Type,Guid? AccountingPeriodId,string Location,string? RemoteMeetingUrl,string? Description,DateTimeOffset FirstCallAt,DateTimeOffset? SecondCallAt);
public record MeetingVersion(int ExpectedVersion);
public record MeetingTransition(int ExpectedVersion,MeetingStatus Status);
public record SessionTransition(int ExpectedVersion,SessionStatus Status);
public record AgendaInput(int ExpectedVersion,Guid? Id,string Title,string? Description,AgendaCategory Category,MeetingReference? RelatedType,Guid? RelatedId);
public record AgendaOrder(int ExpectedVersion,IReadOnlyList<Guid> Ids);
public record RepresentativeChoice(Guid PropertyUnitId,Guid PersonId);
public record ParticipantsInput(int ExpectedVersion,DateOnly ReferenceDate,Guid? AllocationTableId,string Reason,IReadOnlyList<RepresentativeChoice> Representatives);
public record ParticipantPerson(Guid Id,string Name,string? Email,string? MailingAddress);
public record ParticipantHolding(Guid AssociationId,Guid PersonId,UnitPersonRole Role,decimal? Fraction,DateOnly ValidFrom,DateOnly? ValidTo);
public record ParticipantUnit(Guid Id,string Code,decimal? Millesimals,IReadOnlyList<ParticipantHolding> Holdings,Guid? RepresentativeId,IReadOnlyList<string> Anomalies);
public record ParticipantsPreview(DateOnly ReferenceDate,Guid? AllocationTableId,decimal? Denominator,IReadOnlyList<ParticipantPerson> People,IReadOnlyList<ParticipantUnit> Units,string Fingerprint,IReadOnlyList<string> Anomalies);
public record SnapshotDto(Guid Id,int Version,DateTimeOffset CreatedAt,Guid CreatedBy,string Reason,ParticipantsPreview Participants);
public record NoticeInput(int ExpectedVersion,Guid PersonId,NoticeChannel Channel,string Contact);
public record NoticeTransition(int ExpectedVersion,NoticeStatus Status,DateTimeOffset At,string? Reference,string? Notes);
public record NoticeEventDto(Guid Id,NoticeStatus Status,DateTimeOffset DeclaredAt,Guid DeclaredBy,string? Reference,string? Notes,bool VerifiedEvidence=false);
public record NoticeDto(Guid Id,Guid SnapshotId,Guid PersonId,string RecipientName,string Contact,NoticeChannel Channel,NoticeStatus Status,DateTimeOffset? SentAt,IReadOnlyList<NoticeEventDto> Events);
public record ProxyInput(int ExpectedVersion,Guid DelegatorId,Guid DelegateId,IReadOnlyList<Guid> PropertyUnitIds,DateTimeOffset GrantedAt,string? Notes,string? DocumentReference);
public record ProxyTransition(int ExpectedVersion,ProxyStatus Status);
public record ProxyDto(Guid Id,Guid SnapshotId,Guid DelegatorId,Guid DelegateId,ProxyStatus Status,DateTimeOffset GrantedAt,DateTimeOffset? VerifiedAt,Guid? VerifiedBy,string? Notes,string? DocumentReference,IReadOnlyList<Guid> PropertyUnitIds,string DelegatorName,string DelegateName);
public record AttendanceInput(int ExpectedVersion,Guid SessionId,Guid PersonId,AttendanceType Type,Guid? ProxyId,IReadOnlyList<Guid> PropertyUnitIds,DateTimeOffset CheckInAt,string? Notes);
public record AttendanceExit(int ExpectedVersion,DateTimeOffset At);
public record AttendanceDto(Guid Id,Guid SessionId,Guid SnapshotId,Guid PersonId,AttendanceType Type,Guid? ProxyId,Guid? RepresentedById,DateTimeOffset CheckInAt,DateTimeOffset? CheckOutAt,string? Notes,IReadOnlyList<Guid> PropertyUnitIds,decimal Millesimals);
public record SessionDto(Guid Id,MeetingCall Call,DateTimeOffset StartsAt,SessionStatus Status);
public record AgendaDto(Guid Id,int Position,string Title,string? Description,AgendaCategory Category,MeetingReference? RelatedType,Guid? RelatedId,string Status="Planned");
public record MeetingDto(Guid Id,Guid CondominiumId,Guid? AccountingPeriodId,string Title,MeetingType Type,MeetingStatus Status,string Location,string? RemoteMeetingUrl,string? Description,Guid CreatedBy,DateTimeOffset CreatedAt,DateTimeOffset UpdatedAt,int Version,Guid? CurrentSnapshotId,IReadOnlyList<SessionDto> Sessions,IReadOnlyList<AgendaDto> Agenda);
public record AbsenceInput(int ExpectedVersion,Guid SessionId,Guid PersonId,string Reason);
public record AbsenceDto(Guid Id,Guid SessionId,Guid PersonId,string Reason,DateTimeOffset At);
public record MeetingDetails(MeetingDto Meeting,IReadOnlyList<SnapshotDto> Snapshots,IReadOnlyList<NoticeDto> Notices,IReadOnlyList<ProxyDto> Proxies,IReadOnlyList<AttendanceDto> Attendances,IReadOnlyList<AbsenceDto> Absences);
public record MeetingHistoryDto(int Version,DateTimeOffset At,Guid ActorId,string Action,string ContentJson);
public interface IMeetingService
{
 Task<IReadOnlyList<MeetingDto>> List(Guid condo,Guid? period,CancellationToken ct);
 Task<MeetingDetails> Details(Guid condo,Guid id,CancellationToken ct);
 Task<MeetingDetails> Save(Guid condo,Guid? id,MeetingInput input,CancellationToken ct);
 Task<MeetingDetails> Transition(Guid condo,Guid id,MeetingTransition input,CancellationToken ct);
 Task<MeetingDetails> Session(Guid condo,Guid id,Guid session,SessionTransition input,CancellationToken ct);
 Task<MeetingDetails> Agenda(Guid condo,Guid id,AgendaInput input,CancellationToken ct);
 Task<MeetingDetails> DeleteAgenda(Guid condo,Guid id,Guid item,MeetingVersion input,CancellationToken ct);
 Task<MeetingDetails> Reorder(Guid condo,Guid id,AgendaOrder input,CancellationToken ct);
 Task<ParticipantsPreview> PreviewParticipants(Guid condo,Guid id,ParticipantsInput input,CancellationToken ct);
 Task<MeetingDetails> Consolidate(Guid condo,Guid id,ParticipantsInput input,CancellationToken ct);
 Task<MeetingDetails> Notice(Guid condo,Guid id,NoticeInput input,CancellationToken ct);
 Task<MeetingDetails> NoticeStatus(Guid condo,Guid id,Guid notice,NoticeTransition input,CancellationToken ct);
 Task<MeetingDetails> Proxy(Guid condo,Guid id,ProxyInput input,CancellationToken ct);
 Task<MeetingDetails> ProxyStatus(Guid condo,Guid id,Guid proxy,ProxyTransition input,CancellationToken ct);
 Task<MeetingDetails> Attend(Guid condo,Guid id,AttendanceInput input,CancellationToken ct);
 Task<MeetingDetails> Absence(Guid condo,Guid id,AbsenceInput input,CancellationToken ct);
 Task<MeetingDetails> Leave(Guid condo,Guid id,Guid attendance,AttendanceExit input,CancellationToken ct);
 Task<IReadOnlyList<MeetingHistoryDto>> History(Guid condo,Guid id,CancellationToken ct);
}
